PRAGMA defer_foreign_keys = ON;

create table "subject" ("id" text not null primary key, "isIdentified" integer not null, "externalId" text, "identityProvider" text, "lastIpAddress" text, "subjectTimezone" text, "createdAt" integer default CURRENT_TIMESTAMP not null, "updatedAt" integer default CURRENT_TIMESTAMP not null);

create table "domain" ("id" text not null primary key, "name" text not null, "description" text, "allowedOrigins" text, "isVerified" integer not null, "isActive" integer not null, "createdAt" integer default CURRENT_TIMESTAMP not null, "updatedAt" integer default CURRENT_TIMESTAMP not null);

create unique index "unique_c_domain_name" on "domain" ("name");

create table "consentPolicy" ("id" text not null primary key, "version" text not null, "type" text not null, "name" text not null, "effectiveDate" integer not null, "expirationDate" integer, "content" text not null, "contentHash" text not null, "isActive" integer not null, "createdAt" integer default CURRENT_TIMESTAMP not null);

create table "consentPurpose" ("id" text not null primary key, "code" text not null, "name" text not null, "description" text not null, "isEssential" integer not null, "dataCategory" text, "legalBasis" text, "isActive" integer not null, "createdAt" integer default CURRENT_TIMESTAMP not null, "updatedAt" integer default CURRENT_TIMESTAMP not null);

create table "consent" ("id" text not null primary key, "subjectId" text not null, "domainId" text not null, "policyId" text, "purposeIds" text not null, "metadata" text, "ipAddress" text, "userAgent" text, "status" text not null, "withdrawalReason" text, "givenAt" integer default CURRENT_TIMESTAMP not null, "validUntil" integer, "isActive" integer not null, constraint "consent_subject_subject_fk" foreign key ("subjectId") references "subject" ("id") on delete restrict on update restrict, constraint "consent_domain_domain_fk" foreign key ("domainId") references "domain" ("id") on delete restrict on update restrict, constraint "consent_consentPolicy_policy_fk" foreign key ("policyId") references "consentPolicy" ("id") on delete restrict on update restrict);

create table "auditLog" ("id" text not null primary key, "entityType" text not null, "entityId" text not null, "actionType" text not null, "subjectId" text, "ipAddress" text, "userAgent" text, "changes" text, "metadata" text, "createdAt" integer default CURRENT_TIMESTAMP not null, "eventTimezone" text not null, constraint "auditLog_subject_subject_fk" foreign key ("subjectId") references "subject" ("id") on delete restrict on update restrict);

create table "consentRecord" ("id" text not null primary key, "subjectId" text not null, "consentId" text, "actionType" text not null, "details" text, "createdAt" integer default CURRENT_TIMESTAMP not null, constraint "consentRecord_subject_subject_fk" foreign key ("subjectId") references "subject" ("id") on delete restrict on update restrict, constraint "consentRecord_consent_consent_fk" foreign key ("consentId") references "consent" ("id") on delete restrict on update restrict);

create table "private_c15t_settings" ("key" text primary key, "value" text not null);

